use std::collections::HashMap;

fn main() {
    let model_data: HashMap<String, HashMap<String, i32>> = serde_json::from_reader(
        std::fs::File::open(std::env::args().nth(1).expect("input")).expect("file.open"),
    )
    .expect("serde_json.from_reader");

    let base_score = -model_data
        .values()
        .flat_map(|x| x.values().map(|&x| x as i64))
        .sum::<i64>() as f32
        * 0.5;
    fn codegen_scoremap(score_map: &HashMap<String, i32>) -> String {
        format!(
            "phf::phf_map! {{ {} }}",
            score_map
                .iter()
                .map(|(k, v)| format!("{k:?} => {v},"))
                .collect::<String>()
        )
    }

    println!(
        r#"//! this file is auto-generated by gen-embedded-model

pub const MODEL: peridot_tp_budoux::EmbeddedModel = peridot_tp_budoux::EmbeddedModel {{
    base_score: {base_score} as f32,
    uw1_score: {uw1_score},
    uw2_score: {uw2_score},
    uw3_score: {uw3_score},
    uw4_score: {uw4_score},
    uw5_score: {uw5_score},
    uw6_score: {uw6_score},
    bw1_score: {bw1_score},
    bw2_score: {bw2_score},
    bw3_score: {bw3_score},
    tw1_score: {tw1_score},
    tw2_score: {tw2_score},
    tw3_score: {tw3_score},
    tw4_score: {tw4_score},
}};"#,
        uw1_score = codegen_scoremap(&model_data["UW1"]),
        uw2_score = codegen_scoremap(&model_data["UW2"]),
        uw3_score = codegen_scoremap(&model_data["UW3"]),
        uw4_score = codegen_scoremap(&model_data["UW4"]),
        uw5_score = codegen_scoremap(&model_data["UW5"]),
        uw6_score = codegen_scoremap(&model_data["UW6"]),
        bw1_score = codegen_scoremap(&model_data["BW1"]),
        bw2_score = codegen_scoremap(&model_data["BW2"]),
        bw3_score = codegen_scoremap(&model_data["BW3"]),
        tw1_score = codegen_scoremap(&model_data["TW1"]),
        tw2_score = codegen_scoremap(&model_data["TW2"]),
        tw3_score = codegen_scoremap(&model_data["TW3"]),
        tw4_score = codegen_scoremap(&model_data["TW4"]),
    );
}
